    'multi-edit.s0b6d227': "Applied history",
    'multi-edit.s5cfcddd': "Saved presets",
    'multi-edit.s480d10d': "Preset name",
    'multi-edit.s10f230d': "History keeps the last 50 applied parameter sets. Named favorites and drafts are saved locally and can be reused across charts; saving with the same name updates it.",
    'multi-edit.s1900e17': "Select an applied parameter set",
    'multi-edit.s3091692': "{p0} · {p1} {p2} {p3}…{p4}`}",
    'multi-edit.se3c12de': "Select a favorite",
    'multi-edit.s9c985fc': "Batch parameters saved locally",
    'multi-edit.s19996f8': "Select objects on the left; adjust, check the preview, then apply. Dashed lines show the result; original objects stay unchanged.",
    'multi-edit.s1640f9b': "Edit mode",
    'multi-edit.s9537636': "Classic batch edit",
    'multi-edit.s5fce32d': "Script edit",
    'multi-edit.s1ead29e': "Clone (batch copy)",
    'multi-edit.sd0e300b': "Multi-line apply",
    'multi-edit.s81122be': "Apply each line separately",
    'multi-edit.s62563b0': "Apply all in time order",
    'multi-edit.se9d5ab4': "Filter conditions",
    'multi-edit.s575aeda': "Value type",
    'multi-edit.s1645ef4': "Modification mode",
    'multi-edit.sa18ddc2': "Batch split",
    'multi-edit.s086e390': "Batch merge",
    'multi-edit.sa3225c6': "Merge: the first value continues from the previous event's end value. Split: samples into linear segments by \"horizontal subdivision × cut density from settings\", skipping text, shader and zero-length events.",
    'multi-edit.sd51950e': "Period: space-separated, _ skips the entry. Perturbation: one number is ±range, two numbers are a range, more numbers are random choices. HitSound uses To; the lower bound is a file name in the project.",
    'multi-edit.s0456d0a': "Classic normal properties are distributed as 1/N…1; Duration, Order and Line use 0…1. Duration chains end-to-start; Order only reorders contents; Line keeps source events and copies them to target lines.",
    'multi-edit.s79d5c05': "Batch edit script",
    'multi-edit.s8a1d50f': "One assignment per line, supporting = += -= *= /=, arithmetic, comparison, && ||, conditional ? value : value, and # comments. JavaScript is not executed; no file or network access; no loops.",
    'multi-edit.sa5dbd4b': "i starts at 0; N is the count; u is 0…1; classic n: notes start at 0, events at 1. t1/t2 are in beats, visibleTime in seconds. Expressions are evaluated in statement order.",
    'multi-edit.sae69bd8': "Writable: {p0}{p1}. Events are sorted separately by type.",
    'multi-edit.s4db201b': "Functions: sin cos tan abs min max floor ceil round sqrt pow clamp lerp ease; constant pi. Example: t1 += i / 4; t2 += i / 4;",
    'multi-edit.s60316f0': "Target line number sequence",
    'multi-edit.s5e5824d': "Time increment (horizontal subdivisions)",
    'multi-edit.sd2cec64': "Keep source events",
    'multi-edit.s3091c5b': "Separate line numbers with spaces; repeats allowed. The first copy keeps its time; each subsequent copy advances by \"horizontal subdivisions ÷ current horizontal subdivision\" beats. If Keep source events is off, selected source events are removed on apply; copies and unselected events are kept, and base events stay on the same layer.",
    'multi-edit.secef59e': "X, Y, rotation and opacity offsets are assigned in target line order; speed and special events keep their values. Easing, Bezier, link groups and unknown properties are preserved.",
    'multi-edit.s00b7dd3': "Show result ghost in the edit area",
    'multi-edit.s684ad73': "Applied batch edit to {p0} objects",
    'noise-area.s5cb983c': "Drag the green control point · Sample continuously, then apply all at once · Esc to cancel all",
