    'noise-area.se62118e': "Flash {p0}s",
    'noise-area.s3c7509f': "No flash",
    'noise-area.s6eabf6d': "{p0}#{p1} {p2}",
    'noise-area.s81b3bb2': "Noise area",
    'noise-fit.s9835372': "Noise pattern",
    'noise-fit.s25e40e2': "Supports PNG, JPEG, WebP, BMP, GIF, AVIF; transparent pixels are kept as blank.",
    'noise-fit.s41852e3': "Ⅱ Pause demo",
    'noise-fit.s1d50e9d': "▶ Play demo",
    'noise-fit.s0e0472c': "Fitting and timing notes",
    'noise-fit.sd39782e': "Higher detail preserves more detail but yields more noise areas. Rectangles fully cover the binary pattern without filling holes; adjacent cells can be merged, and a smaller max rectangle side gives a finer appearance. The first/last appear beats control when each block is born, and each block lives for the specified number of beats; if the lifetime is shorter than the whole appearance process, earlier blocks may disappear first. In the easing graph, the horizontal axis is the elapsed time ratio and the vertical axis is the appeared quantity ratio: Out types start fast then slow, In types start slow then fast. Bounce and elastic arrange by when the ratio is first reached; blocks that have appeared are not retracted when the curve dips; the first and last blocks keep the specified first/last appear beats. The last beat follows the first if not edited; the activation range is relative to each block's birth time. Drag the pattern on the left to move, boxes to scale, dots to rotate; scroll to zoom the pattern. The preview does not write to the chart; images and fonts are used locally only, and the result is a regular, independently editable noise area.",
    'noise-fit.sc9514ab': "Long side {p0} cells · threshold {p1} / 255",
    'noise-fit.s7011734': "Computing…",
    'noise-fit.s98445c4': "Fitting pattern…",
    'noise-fit.s8256364': "{p0} noise areas",
