    'noise-preview.s64fec24': "Noise area {p0}",
    'noise-skin-renderer.s8875622': "Noise skin ",
    'noise-tracking.s41852e3': "Ⅱ Pause demo",
    'noise-tracking.s850ffe3': "Click in the preview to sample; Hold bodies can also be selected; tracking uses the head position. Width and height are symmetric about the center, and the angle follows the judge line (clockwise). The result is regular events; changing the target later will not update them automatically and requires regenerating. Sample points are merged within a 0.2 coordinate and 0.02° angle tolerance; teleports are kept separately.",
    'noise-tracking.s6d81bbc': "Use the dropdown or pick in the preview; while sampling, all judge lines are temporarily shown opaque.",
