    'event-inspector.s382d24a': "Collapse sampling",
    'event-inspector.sf9494d0': "Supports expressions; nv means compute movement at speed n (120 × n per second), derived from the value at the other end and the event duration",
    'event-inspector.sc5b1373': "{p0}: drag in the preview to sample",
