    'global-events.s30160a2': "Yes",
    'global-events.s8bf5c10': "No",
    'global-events.sdb21b0d': "{p0} global events selected",
    'global-events.s90ce677': " · not loaded",
    'global-events.s3c63e9d': "Whole-song distribution",
    'global-events.se13c9ff': "Click to jump to the corresponding time",
    'text-lines.s96de04e': "Rules, font, and error notes",
    'text-lines.s694e21b': "Note textures show the fitting result; cyan is the original glyph. You can select Drag, Tap, or Flick and refit using the corresponding texture ratio. Glyph skeletons are extracted and stroke widths normalized first, reducing stacked notes added to fill thick strokes; horizontal, vertical, and 45° diagonals are preferred, while curves and other diagonals may still use other angles. Skeleton error = 1 − intersection area of notes with the normalized-width skeleton / union area; each separate connected component must also meet the set minimum skeleton coverage (default 95%, adjustable 0–100%). The coverage minimum and error tolerance are independent; lowering it reduces line usage but may miss small strokes; 0% only checks the error. Nothing is generated below the threshold, and the theoretical minimum line count is not guaranteed. Line numbers support the 0 2:8 group-name form and use at most the specified count. Text and fonts are processed only locally; if a system font is missing the browser may fall back, and emoji are skeletonized as monochrome silhouettes. Imported fonts apply only to this session; generated events do not depend on the font. Events are written to base layer 0, compensating for parent lines and other layers; events existing before generation are kept and remain until the next event on that axis. If passing through a Bezier or whole trajectory, split it first. Continued motion after the parent line still affects the result. Existing notes should match the selected type and be zero-speed, X=0, Y offset=0, and the same size; added fake notes are judged one second after the generation beat and produce no hit sound.",
    'text-lines.sf2eef4e': "The error compares skeleton structure and does not require filling the cyan original glyph, nor does it count highlight glow. If the line itself obscures the text, set the participating lines' opacity to 0 first; negative opacity hides notes. Non-default note size controls still affect the actual result.",
    'text-lines.s7419202': "Calculating…",
    'text-lines.s68c9eb8': "Using {p0} / {p1} lines · skeleton error {p2}% / tolerance {p3}% · minimum skeleton coverage {p4}% (required {p5}%)",
    'text-lines.sa907f2c': ". Error or coverage below threshold, so nothing will be generated; increase line count or adjust note size.",
    'text-lines.sbb4a8db': " · threshold met",
    'text-lines.se4dcd3f': "Generated move and rotate events for {p0} lines; can be undone in one step.",
    'trajectory-panel.s71b971a': "e.g. {\"radius\":200}, expression can use radius directly",
    'trajectory-panel.sa4ecb8d': "Syntax and coordinate notes",
    'trajectory-panel.sbc6218f': "Generates X, Y movement and optional rotation events for judge lines here, not notes. t varies over the specified parameter range; θ / theta use radians and pi / π is the circle constant; compatible with vanilla $t$ and Pi. u is trajectory progress 0–1. Supports + - * / ^, comparisons, the ? : operator, and sin cos tan sqrt abs min max floor round lerp clamp ease. Coordinates use the original RPE center origin, X right, Y up (1350×900); angle events are in degrees. After trimming, the full start and end beats are still covered; overall rotation does not change the judge line's own angle. Random curves are identical for the same seed. A trajectory appears as one unit on the X track; dragging and stretching affect X, Y, and angle together; split it when you need normal events.",
    'trajectory-panel.s56fe877': " Auto tangent angle uses numerical differentiation on the transformed curve, with RPE clockwise-positive angles continuously unwrapped across full turns; when enabled, a manually entered angle is kept but not used. Split approximation tolerance is relative to evenly divided fragment events and limits the maximum deviation of coordinates or angles per axis.",
    'trajectory-panel.s2e1a917': "Apply trajectory changes",
    'trajectory-panel.sf248e5c': "Generate whole trajectory event",
    'trajectory-panel.sd9a0c51': " · adjusted, filled in",
    'trajectory-panel.sf36ad83': "Currently previewing a preset draft; parameters above change only after applying it.",
    'trajectory-panel.s636a8ec': "Trajectory parameters filled above; generate or keep adjusting.",
    'trajectory-panel.sa51b1ba': "Custom preset editor",
    'trajectory-panel.sac74843': "Save, Save as, and Export use the JSON in this box. Save changes updates the preset being edited (renaming name also updates the original entry); Save as new preset adds it immediately and appends a copy number on name clashes. Parametric equations use xExpression, yExpression; polar uses mode: \"polar\" and radiusExpression. parameters declares key, label, value, and optional min/max/step.",
    'trajectory-panel.s131f057': "Saved: {p0}. Select it under the \"Custom\" category or keep editing.",
    'trajectory-panel.s7146275': "My trajectories",
    'trajectory-panel.sa2bd587': "Copy the trajectory parameters above into the editor box below; it is saved only after you click Add to custom presets",
    'trajectory-panel.s4a61bde': "Save changes (update original preset)",
    'trajectory-panel.s81bf38c': "Editing: {p0}. Save changes updates this item; Save as new preset keeps the original.",
    'trajectory-panel.s22f4a49': "New preset draft, not saved yet. Click \"Add to custom presets\" to save it locally.",
    'trajectory-panel.s1980bf3': "Preset draft is only in preview; apply the parameters before generating.",
    'trajectory-panel.s25de9dc': "The X track stores one whole trajectory event including Y and optional angle; dragging an endpoint changes the duration as a whole.",
