    'mod-manager.se2ecae2': "Import External Mod",
    'mod-manager.s8d616da': "External mods execute code inside the editor. They can read, modify, or delete charts and settings in the current browser storage or desktop chart library, and may send data over the network. They can also change the UI, chart structure, and editing semantics, producing unknown effects.",
    'mod-manager.sc2a5ae9': "The editor's authors are not responsible for consequences caused by external mods. Download only from trusted sources, and read the source or have AI inspect it before importing; this cannot guarantee a mod is safe. Back up your charts first.",
