    'mod-manager.s6ebce19': "Mod Protocol API 1",
    'mod-manager.s656efc8': "Each package contains mod.json and an entry ES module that exports activate(api). Supports multi-file imports within the package, the full editor object, chart commits, event hooks, UI mounting, preview overlays, hotkeys, and automatic cleanup.",
    'mod-manager.s1b4dfbd': "Mods run in the editor page with no permission sandbox. Arbitrary direct modifications cannot be guaranteed to unload and restore cleanly; prefer api.patch / api.dispose, and disable and reload on errors.",
    'mod-manager.scda426f': "Full protocol: protocols/MOD-PROTOCOL.zh-CN.md · API: window.rpenMods.editor · Safe start: ?mods=off",
