    'storage-panel.s3383bb1': "Local storage and external backups",
    'storage-panel.s7d9c772': "The chart library and autosaves belong to the same site data. Persistence reduces the risk of browser eviction but cannot withstand actively clearing site data; keep external PEZ backups. Libraries in different browsers or addresses are independent.",
    'storage-panel.sdc43cec': "Desktop settings are stored together in the preferences folder of the current chart library, so they carry over automatically after updating or moving the app without copying the program folder. The library stores charts as individual files with deduplicated assets, and the index can be rebuilt if corrupted. Version history is saved with the library, and full library backups and moves include it. Recovery records and the recycle bin remain inside the library, so save a separate folder backup or PEZ. The first migration keeps the old database.",
