    'agent-chart-tools.sf3fa163': "List all chart tools and the directly callable commands they map to. For curve trajectories, curve notes, text assembly, and noise field patterns/tracking, prefer the native computation commands; do not merely open a panel or claim they cannot be generated. Use chart_templates(command) to inspect specific parameters.",
    'agent-chart-tools.sd9df6ae': "List all built-in and user-defined presets, expressions, and parameters of the native curve trajectory generator, filterable by name or id; fully custom parametric equations/polar coordinates are also supported.",
    'agent-chart-tools.sc5d76a3': "Call the native curve trajectory generator directly: preset/parametric equation/polar coordinates, parameter dictionary, clipping, rotation, scaling, start alignment, independent XY easing, tangent rotation. output=trajectory saves a whole trajectory, events generates normal events; eventIndex can update an existing whole trajectory, and replace requires key approval on conflicts. Time is in local beats of the target line, one undo.",
    'agent-chart-tools.s8d0aeb1': "The specified event is not a whole curve trajectory",
    'agent-chart-tools.s577626f': "Preset does not exist or the name is duplicated; query trajectory_presets first",
    'agent-chart-tools.s67c90c6': "Split the specified whole curve trajectory into normal X/Y movement and optional rotation events, reusing native segment count, simplification, and tolerance, one undo.",
    'agent-chart-tools.sd0b8713': "Split curve trajectory",
    'agent-chart-tools.s7906f9d': "Call the native curve note filler: generates Tap/Drag/Flick from start/end beat and X coordinates, horizontal-line subdivision × density, and easing; intermediate notes do not duplicate the start/end endpoints. Notes on the same beat can be generated horizontally. Time is in local beats of that line, one undo.",
    'agent-chart-tools.s7a90672': "Target judge line does not exist",
    'agent-chart-tools.sfbba660': "The current parameters will not generate intermediate notes; adjust the range or density",
    'agent-chart-tools.sd2ee023': "Call native noise field tracking: target is a judge line or its notes. Accounts for parent lines, layering, multipliers, fall, and jumps to generate noise fields that follow the target's position and angle within the global start/end beats. If the source object is modified later, re-run tracking. One undo.",
    'agent-chart-tools.sfd5c03e': "Native noise field pattern: text plus font, or chart image assets; supports binarization, precision, rectangle merging, layout, reveal order, appear easing, and activation. For images use an image asset path, or a local image already selected in the pattern panel. analyzeOnly=true returns only the count without generating; generating is one undo.",
    'agent-chart-tools.s8d35b04': "Image asset does not exist",
    'agent-chart-tools.sa905723': "Image exceeds 64 megapixels",
    'agent-chart-tools.s84b7ddd': "Generate noise field pattern",
    'agent-chart-tools.s6c14f6e': "Native text assembly: spell text from a specified font skeleton plus existing judge lines and zero-speed Tap/Drag/Flick notes, preferring horizontal/vertical/45 degrees and compensating for parent lines/layering. If tolerance or minimum coverage is not met, nothing is generated and the reason is returned. analyzeOnly only analyzes; replace requires key approval on conflicts, one undo.",
    'agent-chart-tools.se4ca0b4': "Analysis only, nothing generated",
    'agent-chart-tools.s775c7d7': "Fit error or skeleton coverage did not meet the requirement; add usable judge lines or adjust the parameters",
    'agent-chart-tools.s5f27b55': "Read/set multi-line editing line numbers or groups, enabled state, note/event mode, note merging, and single-line width; only changes the workspace, not the chart or playhead. lines is an array of line numbers or a \"0 2:8 group name\" expression.",
    'agent-chart-tools.s654934a': "List loaded global event types/columns/sources/default values, and page through or replace column events; reuses native validation, mod sources, and undo, supports temporary placeholder types, and unknown types are read-only.",
    'agent-chart-tools.sdd70d01': "Global event type or column does not exist",
    'agent-chart-tools.s1057f5d': "This global event is not editable, or events is missing",
    'agent-chart-tools.s634a0c2': "Global event validation failed",
    'agent-chart-tools.s17d7c54': "Modify global event: {p0} / {p1}",
    'agent-chart-tools.sa412903': "AI · Edit global events",
    'agent-chart-tools.s3c73225': "Global event changes were not applied",
    'agent-component-tools.s691077e': "Generic low-level entry point for editor components, for functionality not covered by dedicated commands. describe lists available targets and existing methods/properties, get reads data properties; call invokes existing methods, set modifies existing writable properties. Modifications/calls are approved as dangerous operations and behave like the corresponding native methods, with no guarantee of undo; verify parameters and semantics with editor_source first and prefer structured commands. In arguments/value, {$workspaceFile:\"relative path\",name:\"file name\"} is resolved by the host to a local File, supports native import methods, and does not send binary data to the model. Credentials, the Agent itself, prototype constructors, and arbitrary global objects are not accessible.",
    'agent-component-tools.s43795ad': "Component does not exist; use describe to query target first",
    'agent-component-tools.s120e7b8': "Component member is unavailable",
    'agent-component-tools.s19d994f': "get only reads data properties; for accessors, consult the source or use a dedicated command",
    'agent-component-tools.s22062d4': "Member is not a method",
    'agent-component-tools.s1a53083': "Property is not writable",
    'agent-component-tools.s13f8be2': "Arguments are nested too deeply",
    'agent-component-tools.sb205fcf': "File workspace is unavailable",
    'agent-component-tools.s0e010b4': "Workspace file does not exist",
    'agent-component-tools.s4693980': "{p0} {p1}.{p2}",
    'agent-component-tools.sb1fb011': "Call",
