    'audio-separation-guide.s226a312': "Stem separation guide",
    'audio-separation-guide.sf3ce522': "Where: Chart Tools → Audio Analysis → Stems & Analysis Source",
    'audio-separation-guide.scdf2bd2': "Windows / macOS / Linux desktop",
    'audio-separation-guide.sdbaa6ec': "The first time you open Audio Analysis, read the disk usage notice and choose a storage location; a non-system drive with plenty of space is recommended. A new environment, models, and caches can take several GB to tens of GB; cancelling the selection does not start installation.",
    'audio-separation-guide.s5b6bf9a': "Click “One-click separation setup” and choose CPU or NVIDIA acceleration. No need to install Python first or type commands; CPU works on supported desktop systems.",
    'audio-separation-guide.sd965f44': "Wait for the download, installation, and check to finish. First use requires network access and several GB of free space; after upgrading the editor, the installed environment is reused.",
    'audio-separation-guide.s586c036': "Choose “4 stems” or “6 stems”, then click “Separate current music”. The first separation downloads the selected model; later runs use the cache.",
    'audio-separation-guide.se7e62d3': "Select sources such as vocals, drums, and bass; keep at least one. The play button plays the mix of the selected stems, with speed and pitch preservation working as usual; each stem's waveform/spectrum is shown in its own color.",
    'audio-separation-guide.sd504b19': "Web: import stems, then analyze",
    'audio-separation-guide.sab952a0': "The web version does not run local Demucs directly. The simplest route is to separate the same music in RPEN desktop, then export the needed stems as WAV.",
    'audio-separation-guide.sab22037': "You can also use installed tools such as UVR / Demucs, selecting the same complete music and exporting stems. Do not trim the leading silence, change speed, or edit further.",
    'audio-separation-guide.sc7cf867': "Return to this page, click “Import stems”, and select multiple audio files at once. Phones and tablets can also pick these results from the files app.",
    'audio-separation-guide.sbe863fd': "Select one or more stems to play and analyze, then use the editor's play button directly. All files are aligned to the start of the original music and share the same chart offset; no separate stem start point is set.",
    'audio-separation-guide.s984d1f8': "The selected results are used for playback, waveform, spectrum, and default AI onset detection, and revert to the original audio after leaving the chart. The web version needs no Python; DDC / Mapperatorinator local models still require desktop.",
    'audio-separation-guide.s775a104': "How do I use it on the web, phones, and tablets?",
    'audio-separation-guide.s4fe94af': "What if I don't have a desktop computer?",
    'audio-separation-guide.s6f61f07': "After separating on desktop, use “Export” next to each stem to save the WAVs you need, transfer the files to the other device, then “Import stems” on the web. The original music file stays unchanged, and the playback source switch only applies while this chart is open.",
    'audio-separation-guide.sfa0c709': "This version needs external separation results first: process on another computer and transfer the WAVs, or use a separation tool you trust and download the results. RPEN web does not automatically upload music to third-party services.",
    'audio-separation-guide.s9fc3a43': "Devices & FAQ",
    'audio-separation-guide.se2383c0': "One-click setup targets Windows x64, macOS on Apple silicon, and Linux x64. On Intel Mac, ARM Linux, and ARM Windows, use an existing environment or import external separation results. On macOS choose CPU; NVIDIA acceleration is for compatible Windows / Linux GPUs.",
    'audio-separation-guide.s82bc9cd': "Download failed: check your network and disk space, then click “One-click setup” again. Already downloaded files are reused where possible; a failure does not modify the chart or original music. Advanced settings let you select an existing environment or install with an existing Python.",
    'audio-separation-guide.sec2c246': "Four stems are vocals, drums, bass, and other. Six stems also include guitar and piano but may still bleed; import external results if you need a different model.",
    'audio-separation-guide.sc334334': "Separation results belong to the current music's analysis session and are not written into the chart package. Export WAVs to keep them or move across devices; separating the same music again locally reuses the cache.",
    'audio-separation-guide.se8c1f1d': "“Model & cache location” lets you view and migrate data; “Clear audio cache”, after confirmation, clears separation, onset detection, download, and temporary caches for all charts, while keeping models, runtime environments, original music, and charts.",
    'audio-separation-guide.s7bdb25d': "Local separation needs no AI API key, and audio is never uploaded. The network is used only to download environments, dependencies, and models.",
